import { useMutation, type UseMutationOptions } from "@tanstack/react-query";
import { cancelChildApplicationHandler } from "../handlers/cancelChildApplicationHandler";
import type { ApiError } from "../runtime/client";
import type { TeamPartition } from "../types/TeamPartition";

type Data = Awaited<ReturnType<typeof cancelChildApplicationHandler>>;
type Vars = { teamPk: TeamPartition; applicationId: string };

export function useCancelChildApplication(
  options?: Omit<UseMutationOptions<Data, ApiError, Vars>, "mutationFn">,
) {
  return useMutation<Data, ApiError, Vars>({
    mutationFn: (vars) => cancelChildApplicationHandler(vars.teamPk, vars.applicationId),
    ...options,
  });
}
